{
  "name": "surfing-pelican",
  "version": "1.0.0",
  "description": "An animated, non-interactive surfing pelican diorama built with Three.js.",
  "type": "module",
  "scripts": {
    "check": "esbuild main.js --bundle --format=esm --outfile=/dev/null"
