* {
  box-sizing: border-box;
}

html,
body {
  height: 100%;
}

body {
  margin: 0;
  overflow: hidden;
  background: #9fd4e6;
  font-family: "Avenir Next", "Trebuchet MS", "Segoe UI", system-ui, sans-serif;
  color: #12303a;
}

#stage {
  position: fixed;
  inset: 0;
}

#scene {
  display: block;
