  background: radial-gradient(ellipse at center, transparent 58%, rgba(10, 48, 61, 0.22) 100%);
}

.caption {
  position: absolute;
  left: clamp(16px, 4vw, 40px);
  bottom: clamp(16px, 4vw, 40px);
  max-width: 360px;
  pointer-events: none;
  background: rgba(255, 253, 245, 0.92);
  border: 2px solid #12303a;
  border-radius: 6px;
  box-shadow: 6px 6px 0 #12303a;
  padding: 16px 18px 14px;
}

.caption__kicker {
