function shadowed(mesh) {
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

// --- Ocean: a wide plane animated with layered sine swells ------------------
const oceanGeometry = new THREE.PlaneGeometry(120, 80, 96, 56);
oceanGeometry.rotateX(-Math.PI / 2);
const oceanBase = oceanGeometry.attributes.position.array.slice();
const ocean = new THREE.Mesh(
  oceanGeometry,
  new THREE.MeshStandardMaterial({
    color: 0x0d7d8c,
    roughness: 0.32,
    metalness: 0.08,
  }),
);
ocean.position.set(0, -0.55, -14);
ocean.receiveShadow = true;
scene.add(ocean);

function waveHeightAt(x, z, t) {
  return (
    Math.sin(x * 0.22 + t * 0.9) * 0.22 +
    Math.sin(z * 0.3 - t * 0.7) * 0.18 +
    Math.sin((x + z) * 0.12 + t * 0.45) * 0.26
  );
}

function updateOcean(t) {
  const pos = oceanGeometry.attributes.position;
  for (let i = 0; i < pos.count; i += 1) {
    const x = oceanBase[i * 3];
    const z = oceanBase[i * 3 + 2];
    pos.setY(i, waveHeightAt(x, z, t) * MOTION + waveHeightAt(x, z, 0) * (1 - MOTION));
  }
  pos.needsUpdate = true;
  oceanGeometry.computeVertexNormals();
}

// --- The hero wave: a curling face the pelican rides -----------------------
// Built from a plane bent through a breaking-wave profile: a steep face
// rising from the trough, then a lip that curls forward over the barrel.
function buildWaveFace() {
  const geo = new THREE.PlaneGeometry(30, 7.2, 72, 36);
  const pos = geo.attributes.position;
  for (let i = 0; i < pos.count; i += 1) {
    const x = pos.getX(i);
    const v = (pos.getY(i) + 3.6) / 7.2; // 0 at trough, 1 at lip
    // Steep face that leans back, then curls forward at the top.
    const rise = Math.pow(v, 1.25) * 5.4;
    const leanBack = -Math.pow(v, 2) * 1.5;
    const curlT = THREE.MathUtils.smoothstep(v, 0.68, 1.0);
    const curlForward = curlT * curlT * 3.4;
    const curlDrop = curlT * curlT * 1.7;
    // The ends of the wave peel lower so the barrel feels open in the middle.
    const edgeDrop = Math.pow(Math.abs(x) / 15, 2.4) * 1.5 * v;
    pos.setXYZ(i, x, rise - curlDrop - edgeDrop, leanBack + curlForward);
  }
  geo.computeVertexNormals();
  return geo;
}

const waveGroup = new THREE.Group();
waveGroup.position.set(0, 0.1, -3.4);
scene.add(waveGroup);

const waveFace = new THREE.Mesh(
  buildWaveFace(),
  new THREE.MeshStandardMaterial({
    color: 0x159fb0,
    roughness: 0.28,
    metalness: 0.05,
    side: THREE.DoubleSide,
  }),
);
waveFace.receiveShadow = true;
waveGroup.add(waveFace);

// Translucent inner barrel wall so the curl reads as a tube of water.
const barrel = new THREE.Mesh(
  new THREE.CylinderGeometry(1.55, 1.55, 26, 24, 1, true, Math.PI * 0.15, Math.PI * 0.95),
  new THREE.MeshStandardMaterial({
    color: 0x2fc3cf,
    roughness: 0.2,
    metalness: 0.05,
    transparent: true,
    opacity: 0.5,
    side: THREE.DoubleSide,
  }),
);
barrel.rotation.z = Math.PI / 2;
barrel.rotation.y = Math.PI / 2;
barrel.position.set(0, 3.1, 0.4);
waveGroup.add(barrel);

// Foam lip: a chain of soft white blobs tracing the curling crest.
const foamMaterial = standard(0xffffff, { roughness: 0.95 });
const foamBlobs = [];
for (let i = 0; i < 34; i += 1) {
  const x = -13.5 + (i / 33) * 27;
  const edgeDrop = Math.pow(Math.abs(x) / 15, 2.4) * 1.5;
  const blob = new THREE.Mesh(new THREE.SphereGeometry(0.32 + Math.random() * 0.3, 10, 8), foamMaterial);
  blob.position.set(x + (Math.random() - 0.5) * 0.4, 3.85 - edgeDrop + (Math.random() - 0.5) * 0.25, 1.9 + (Math.random() - 0.5) * 0.4);
  blob.scale.set(1.3, 0.55, 0.8);
  waveGroup.add(blob);
  foamBlobs.push({ mesh: blob, seed: Math.random() * Math.PI * 2, baseY: blob.position.y });
}
// Whitewater churning at the base of the wave.
for (let i = 0; i < 26; i += 1) {
  const x = -13 + Math.random() * 26;
  const puff = new THREE.Mesh(new THREE.SphereGeometry(0.35 + Math.random() * 0.55, 10, 8), foamMaterial);
  puff.position.set(x, 0.15 + Math.random() * 0.3, 0.6 + Math.random() * 1.4);
  puff.scale.set(1.5, 0.4, 0.9);
  waveGroup.add(puff);
  foamBlobs.push({ mesh: puff, seed: Math.random() * Math.PI * 2, baseY: puff.position.y });
}

